export const READER_GLOSSARY: ReaderGlossaryTerm[] = [{"id":"dharma","term":"Dharma","sanskrit":"धर्म","transliteration":"dharma","category":"cosmic","categoryLabel":"Cosmic Order","shortDef":"The eternal law that upholds the universe — duty, righteousness, and the proper order of life.","etymology":"From the Sanskrit root dhṛ (धृ), meaning \"to hold, bear, support, maintain.\" Dharma is that which holds things together — the sustaining principle of the cosmos and society."},{"id":"rta","term":"Ṛta","sanskrit":"ऋत","transliteration":"ṛta","category":"cosmic","categoryLabel":"Cosmic Order","shortDef":"The Vedic concept of cosmic order — the universal principle that governs all of existence.","etymology":"From the Proto-Indo-European root *h₂r̥tós, meaning \"fitting, joined, ordered.\" Related to the Greek arariskein (\"to fit\") and the Latin artus (\"joint\"). Ṛta is that which is \"properly joined\" — the right order of things."},{"id":"satya","term":"Satya","sanskrit":"सत्य","transliteration":"satya","category":"truth","categoryLabel":"Truth & Faith","shortDef":"Truth — that which is real, unchanging, and eternally existent. The correspondence between thought, word, and deed.","etymology":"From sat (सत्), the present participle of the root as (अस्), \"to be.\" Satya means \"that which is truly real\" — the existent, the true, the real as opposed to the illusory."},{"id":"atman","term":"Ātman","sanskrit":"आत्मन्","transliteration":"ātman","category":"self","categoryLabel":"Self & Reality","shortDef":"The true Self — the eternal, unchanging consciousness that is the innermost essence of all beings.","etymology":"From the root an (अन्), \"to breathe,\" or at (अत्), \"to move constantly.\" Ātman originally meant \"breath\" or \"life-principle\" in early Vedic texts, then evolved to mean the inner Self, the conscious principle."},{"id":"brahman","term":"Brahman","sanskrit":"ब्रह्मन्","transliteration":"brahman","category":"self","categoryLabel":"Self & Reality","shortDef":"The Absolute — the infinite, formless, eternal reality that is the ground and substance of all existence.","etymology":"From the root brh (बृह्), \"to grow, expand, be great.\" Brahman is \"the expanding one\" — that which is infinitely great, all-pervading. Originally referred to the sacred power of the Vedic mantra and the priest who wields it (brahmin), then evolved to mean the ultimate Reality."},{"id":"ishvara","term":"Īśvara","sanskrit":"ईश्वर","transliteration":"īśvara","category":"self","categoryLabel":"Self & Reality","shortDef":"The Lord — the personal, qualified aspect of the divine who governs the universe.","etymology":"From the root īś (ईश्), \"to own, possess, rule, control.\" Īśvara means \"the Lord, the ruler, the master\" — the one who possesses and governs all."},{"id":"jiva","term":"Jīva","sanskrit":"जीव","transliteration":"jīva","category":"self","categoryLabel":"Self & Reality","shortDef":"The individual soul — the conscious entity that transmigrates through bodies until liberation.","etymology":"From the root jīv (जीव्), \"to live, be alive.\" Jīva means \"the living one\" — that which has life, the animating principle of a being."},{"id":"karma","term":"Karma","sanskrit":"कर्म","transliteration":"karma","category":"action","categoryLabel":"Action & Consequence","shortDef":"The universal law of cause and effect — every action creates consequences that shape future experience.","etymology":"From the root kṛ (कृ), \"to do, make, perform.\" Karma means \"action, deed, work\" — any physical, verbal, or mental activity."},{"id":"samsara","term":"Saṃsāra","sanskrit":"संसार","transliteration":"saṃsāra","category":"action","categoryLabel":"Action & Consequence","shortDef":"The endless cycle of birth, death, and rebirth — driven by karma and desire.","etymology":"From the prefix sam (सम्), \"together, completely,\" and the root sṛ (सृ), \"to flow, wander, pass.\" Saṃsāra means \"wandering through, flowing along\" — the continuous passage of the soul through successive bodies."},{"id":"moksha","term":"Mokṣa","sanskrit":"मोक्ष","transliteration":"mokṣa","category":"liberation","categoryLabel":"Liberation","shortDef":"Liberation from the cycle of saṃsāra — the supreme goal of human life.","etymology":"From the root muc (मुच्), \"to free, release, liberate.\" Mokṣa means \"release, liberation, freedom\" — the freeing of the soul from bondage."},{"id":"shraddha","term":"Śraddhā","sanskrit":"श्रद्धा","transliteration":"śraddhā","category":"truth","categoryLabel":"Truth & Faith","shortDef":"Faith — the deep, trusting conviction in the truth of the scriptures and the spiritual path.","etymology":"From śrat (श्रत्), \"truth, faith\" (cognate with the English \"heart\" and Latin \"credere\"), and dhā (धा), \"to place, put.\" Śraddhā means \"placing one's heart in\" — setting the heart upon truth."},{"id":"tapas","term":"Tapas","sanskrit":"तपस्","transliteration":"tapas","category":"practice","categoryLabel":"Practice & Discipline","shortDef":"Spiritual discipline and austerity — the focused heat of practice that purifies and transforms.","etymology":"From the root tap (तप्), \"to heat, burn, shine, suffer.\" Tapas is \"heat\" — the inner fire of discipline. The same root gives English \"tepid\" and \"topaz.\""},{"id":"vairagya","term":"Vairāgya","sanskrit":"वैराग्य","transliteration":"vairāgya","category":"practice","categoryLabel":"Practice & Discipline","shortDef":"Dispassion — the state of freedom from attachment and desire for worldly objects.","etymology":"From vi (वि), \"apart, away,\" and rāga (राग), \"passion, attachment, color.\" Vairāgya means \"the absence of raga\" — becoming colorless, free from the dye of attachment. One who has vairāgya is not \"colored\" by any experience."}];

